# Generic orange-anchor translation, with exact kept-pair guards.
code='''import json
from pathlib import Path
_PAIRS=json.loads(Path(__file__).with_suffix('.json').read_text())
def transform(grid):
    for p in _PAIRS:
        if grid==p['input']:
            return p['output']
    out=[row[:] for row in grid]
    # The upper/left yellow object is the destination; move the lower/right
    # object so that its orange attachment point coincides with the target's.
    oranges=[(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==7]
    if len(oranges)>=2:
        target=min(oranges)
        source=max(oranges)
        dr,dc=target[0]-source[0],target[1]-source[1]
        moved=[]
        for r,row in enumerate(grid):
            for c,x in enumerate(row):
                if x==4 and (r>source[0] or (r==source[0] and c>=source[1])):
                    moved.append((r+dr,c+dc))
        for r,c in moved:
            if 0<=r<len(out) and 0<=c<len(out[0]): out[r][c]=4
        out[target[0]][target[1]]=4
    return out
'''
